mapper.select:
SELECT

FROM ai_code_rule
WHERE tenant_id = #{tenantId}
  AND del_flag = '0'

    AND rule_code LIKE CONCAT('%', #{ruleCode}, '%')


    AND rule_name LIKE CONCAT('%', #{ruleName}, '%')


    AND scene = #{scene}


    AND category = #{category}


    AND status = #{status}

ORDER BY builtin DESC, update_time DESC, id DESC

SELECT rule.id, rule.tenant_id AS tenantId, rule.rule_code AS ruleCode, rule.rule_name AS ruleName, rule.scene, rule.category, rule.source_object_id AS sourceObjectId, rule.source_object_code AS sourceObjectCode, rule.template, rule.status, rule.builtin, rule.in_code_list AS inCodeList, rule.version_no AS versionNo, rule.remark, rule.create_time AS createTime, rule.update_time AS updateTime, (SELECT COUNT(1) FROM ai_code_rule_segment segment WHERE segment.tenant_id = rule.tenant_id AND segment.rule_id = rule.id AND segment.del_flag = '0') AS segmentCount, CASE WHEN EXISTS ( SELECT 1 FROM ai_code_rule_segment segment WHERE segment.tenant_id = rule.tenant_id AND segment.rule_id = rule.id AND segment.del_flag = '0' ) THEN 'STRUCTURED' ELSE 'LEGACY' END AS compatibilityMode FROM ai_code_rule rule WHERE rule.tenant_id = #{tenantId} AND rule.del_flag = '0'
AND rule.rule_code LIKE CONCAT('%', #{ruleCode}, '%')
AND rule.rule_name LIKE CONCAT('%', #{ruleName}, '%')
AND rule.category = #{category}
AND rule.status = #{status}
ORDER BY rule.builtin DESC, rule.update_time DESC, rule.id DESC

SELECT

FROM ai_code_rule
WHERE tenant_id = #{tenantId}
  AND del_flag = '0'
  AND rule_code = #{ruleCode}
LIMIT 1

SELECT

FROM ai_code_rule
WHERE tenant_id = #{tenantId}
  AND del_flag = '0'
  AND id = #{id}
LIMIT 1

SELECT COUNT(1)
FROM ai_code_rule
WHERE tenant_id = #{tenantId}
  AND del_flag = '0'
  AND rule_code = #{ruleCode}

    AND id != #{excludeId}
